use std::fs
use std::strings

fn main() {
    let input = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut left: Vec<int> = []
    let mut right: Vec<int> = []
    let mut root: int = -1
    for line in input.lines() {
        let parts = strings::split_whitespace(line)
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        let mut arg: int = 0
        if parts.len() > 1 {
            arg = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" || cmd == "contains" || cmd == "delete" {
            // locate
            let mut cur = root
            let mut parent: int = -1
            let mut went_left = false
            let mut found = false
            while cur != -1 {
                let k = keys[cur as usize]
                if k == arg {
                    found = true
                    break
                }
                parent = cur
                if arg < k {
                    went_left = true
                    cur = left[cur as usize]
                } else {
                    went_left = false
                    cur = right[cur as usize]
                }
            }
            if cmd == "contains" {
                if found { println("yes") } else { println("no") }
            } else if cmd == "insert" {
                if found {
                    println("dup")
                } else {
                    let idx = keys.len() as int
                    keys.push(arg)
                    left.push(-1)
                    right.push(-1)
                    if parent == -1 {
                        root = idx
                    } else if went_left {
                        left[parent as usize] = idx
                    } else {
                        right[parent as usize] = idx
                    }
                    println("ok")
                }
            } else {
                if !found {
                    println("missing")
                } else {
                    let l = left[cur as usize]
                    let r = right[cur as usize]
                    if l != -1 && r != -1 {
                        let mut sp = cur
                        let mut s = r
                        while left[s as usize] != -1 {
                            sp = s
                            s = left[s as usize]
                        }
                        keys[cur as usize] = keys[s as usize]
                        if sp == cur {
                            right[sp as usize] = right[s as usize]
                        } else {
                            left[sp as usize] = right[s as usize]
                        }
                    } else {
                        let mut child = l
                        if l == -1 { child = r }
                        if parent == -1 {
                            root = child
                        } else if went_left {
                            left[parent as usize] = child
                        } else {
                            right[parent as usize] = child
                        }
                    }
                    println("ok")
                }
            }
        } else if cmd == "inorder" {
            if root == -1 {
                println("<empty>")
            } else {
                let mut st: Vec<int> = []
                let mut top: usize = 0
                let mut out = ""
                let mut first = true
                let mut cur = root
                while cur != -1 || top > 0 {
                    while cur != -1 {
                        if top < st.len() { st[top] = cur } else { st.push(cur) }
                        top += 1
                        cur = left[cur as usize]
                    }
                    top -= 1
                    let n = st[top]
                    if first { first = false } else { out = out + " " }
                    out = out + "${keys[n as usize]}"
                    cur = right[n as usize]
                }
                println("${out}")
            }
        } else if cmd == "height" {
            let mut h = 0
            if root != -1 {
                let mut q: Vec<int> = [root]
                let mut head: usize = 0
                while head < q.len() {
                    let end = q.len()
                    while head < end {
                        let n = q[head]
                        head += 1
                        if left[n as usize] != -1 { q.push(left[n as usize]) }
                        if right[n as usize] != -1 { q.push(right[n as usize]) }
                    }
                    h += 1
                }
            }
            println("${h}")
        } else if cmd == "min" || cmd == "max" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur = root
                if cmd == "min" {
                    while left[cur as usize] != -1 { cur = left[cur as usize] }
                } else {
                    while right[cur as usize] != -1 { cur = right[cur as usize] }
                }
                println("${keys[cur as usize]}")
            }
        }
    }
}

